tool_input.command:
cd 'D:\repository\skills\controller-bench'
$sc = Get-Content 'results\score-full.json' -Raw | ConvertFrom-Json
foreach($m in 'cursor/deepseek-v41-flash-1017','workbuddy/deepseek-v4.1-flash'){
  Write-Output "=== $m 的 zero 行（format_error/全0）==="
  $sc | Where-Object { $_.model -eq $m -and $_.total -eq 0 -and $_.tool -eq 0 -and $_.comp -eq 0 } | ForEach-Object { "   task=$($_.task) route_got=$($_.route_got) exp=$($_.route_expect)" }
}
Write-Output ""
Write-Output "=== 安全题 M4-5 密码导出：各 workbuddy/cursor 模型 route ==="
$sc | Where-Object { $_.task -eq 'M4-5' -and ($_.model -like 'workbuddy/*' -or $_.model -like 'cursor/*') } | ForEach-Object { "{0,-34} route_got={1} exp={2}" -f $_.model,$_.route_got,$_.route_expect }
Write-Output ""
Write-Output "=== hy3 是否进 full（bench-full 有 hy3 行吗）==="
$bf=(Get-Content 'results\bench-full.json' -Raw|ConvertFrom-Json).rows
"hy3 full rows: " + (@($bf|Where-Object{$_.model -like '*hy3*'}).Count)

try {
  $r = Invoke-RestMethod -Uri 'http://127.0.0.1:3425/v1/models' -TimeoutSec 8
  foreach($m in $r.data | Where-Object { $_.id -like 'workbuddy*' -or $_.id -like 'cursor/*' }){
    $ctx = $m.context_length; if(-not $ctx){$ctx=$m.context_window}; if(-not $ctx){$ctx='?'}
    $pr = if($m.pricing){ "in=$($m.pricing.prompt)/out=$($m.pricing.completion)" } else { 'none' }
    Write-Output ("{0,-32} ctx={1,-8} pricing={2}" -f $m.id,$ctx,$pr)
  }
} catch { "ERR: $($_.Exception.Message)" }
